['Here's how you might implement the functions in C. Please note that this doesn't actually do any memory copying, but instead shows the logic behind the process using pointer manipulation and loops.

```c
#include <stdio.h>
#include <string.h>

// Function to copy bytes from one location to another
void copy_bytes(char* dest, const char* src, size_t num) {
    for (size_t i = 0; i < num; ++i) {
        *dest = *src;  // Copy byte
        ++dest;  // Move destination pointer forward
        ++src;   // Move source pointer forward
    }
}

// Function to return length of a string
size_t string_length(const char* str) {
    size_t len = 0;
    while (*str != '\0') {  // Loop until end of the string is found
        ++len;  
        ++str;  // Move pointer forward
    }
    return len;
}

int main() {
    const char* message = "Hello, world!";
    size_t length = string_length(message);

    char buffer[1024];  // Assuming maximum length for the buffer is 1024 characters

    copy_bytes(buffer, message, length + 1);  // +1 to also copy null-terminator

    printf("Copied string: %s\n", buffer);

    return 0;
}
```

This code first calculates the length of the input string using `string_length()`. Then it allocates a buffer and uses `copy_bytes()` to copy the bytes from the message to the buffer. Finally, it prints out the copied string.
