void copy_bytes(char* dest, char* src, int num) {
    memcpy(dest, src, num);  // Copying 'num' bytes from 'src' to 'dest'.
}

int main() {
    const char* source = "Hello";  // The string we want to copy.
    char destination[6];  // Destination buffer for the copied string (extra space for null terminator).

    int num_bytes = strlen(source) + 1;  // Getting the length of the source string including '\0'.
    copy_bytes(destination, source, num_bytes);

    return 0;
}
```

