#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int getMonthlySales() {
    return rand() % 100001; // random number between 0 and 100000
}

void main() {
    srand(time(NULL)); // seed the pseudo-random number generator
    int quarter, month, total_sales[4] = {0}, sales; // initializing variables

    for (month = 1; month <= 12; month++) {
        sales = getMonthlySales(); // calling the function

        if(month <= 3){ // first quarter
            total_sales[quarter] += sales;
        }else if(month > 3 && month <= 6){ // second quarter
            total_sales[1] += sales;
        }else if(month > 6 && month <= 9){ // third quarter
            total_sales[2] += sales;
        }else{ // fourth quarter
            total_sales[3] += sales;
        }

        printf("Month %d Sales: $%d\n", month, sales); // print monthly sales
    }

    for(quarter = 0; quarter < 4; quarter++){
        printf("Total sales for Quarter %d is: $%d\n", (quarter+1), total_sales[quarter]); // print the quarterly totals
    }
}
```
This code first initializes an array of 4 integers, representing the total sales for each quarter. It then generates a random number of sales for each month and adds it to the appropriate quarter's total using a series of `if-else` statements. After generating all sales data, it prints out the results in the two main sections of the code.
