from urllib.parse import urlparse
import requests

def redirect_url(url):
    parsed_url = urlparse(url)
    domain_name = parsed_url.netloc

    if 'www.' in domain_name:
        domain_name = domain_name[4:]  # remove www. from the beginning of domain name

    if '.com' in domain_name:
        domain_name = domain_name[:-4]  # remove .com from the end of domain name

    if domain_name != 'example':
        return "Error 404 - URL not found"
    else:
        try:
            response = requests.get(url)

            if response.status_code == 200:
                # url is redirected here
                pass

            else:
                return 'HTTP Request Failed'

        except requests.exceptions.RequestException as e: 
            return "Error: {}".format(str(e))

    return 'URL successfully redirected.'
```

This code will only work if the URL is a complete one (including protocol, like http or https) and not just path like '/test'. If you want to check local paths, consider using Flask or Django for web development.
