['Here's a simple implementation in C using fread, feof, fopen and fclose functions:

```C
#include <stdio.h>
#define BUFFER_SIZE 1024

int main() {
    FILE *file = NULL;
    FILE *outFile = NULL;
    char buffer[BUFFER_SIZE];
    int checksum = 0, bytesRead = 0;

    // Open the input file in binary mode
    if ((file = fopen("input.txt", "rb")) == NULL) {
        printf("Cannot open file.\n");
        return 1;
    }

    // Read from the file until EOF is reached
    while (!feof(file)) {
        bytesRead = fread(buffer, sizeof(char), BUFFER_SIZE, file);

        if (bytesRead > 0) {
            for (int i = 0; i < bytesRead; ++i) {
                checksum += buffer[i]; // Add each byte to the checksum.
            }

            printf("Bytes read: %d\n", bytesRead);
        }
    }

    fclose(file);

    printf("Checksum: %d\n", checksum);

    // Open the output file in binary mode
    if ((outFile = fopen("output.txt", "wb")) == NULL) {
        printf("Cannot open output file.\n");
        return 1;
    }

    // Write bytes read and checksum to the output file
    fprintf(outFile, "Bytes Read: %d\nChecksum: %d\n", bytesRead, checksum);

    fclose(outFile);

    return 0;
}
```
This program reads binary data from a file and calculates the checksum by adding each byte value. It then writes this information to an output file. Note that it assumes the input file exists in the same directory as the executable, and if not found, will print an error message. 

The `BUFFER_SIZE` constant determines how many bytes to read at once from the file; you can adjust it depending on your needs. Also note that this example is very simple, and doesn't handle errors or edge cases well (for example, if the input file is too large to fit into memory).
']

['Here is an example of C code that accomplishes this task. This example uses fread, fwrite and SHA256 for calculating a checksum. Note that you may need to install OpenSSL library to use `SHA256` function in your system.

```c
#include <stdio.h>
#include <openssl/sha.h>  // You will need to install OpenSSL and include it with -lcrypto

int main() {
    FILE *fp_read, *fp_write;
    char buffer[1024];  // Buffer size can be adjusted as needed
    unsigned char checksum[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;
    int bytesRead, i;

    fp_read = fopen("input.txt", "rb");  // Open the file in binary mode for reading
    if (fp_read == NULL) {
        printf("Could not open input.txt\n");
        return -1;
    }

    fp_write = fopen("output.txt", "wb");  // Open the file in binary mode for writing
    if (fp_write == NULL) {
        printf("Could not open output.txt\n");
        return -1;
    }

    SHA256_Init(&sha256);

    while((bytesRead = fread(buffer, 1, sizeof(buffer), fp_read)) > 0) {
        SHA256_Update(&sha256, buffer, bytesRead);
    }

    SHA256_Final(checksum, &sha256);

    int isEmpty = 1;  // Assume the buffer is empty initially
    for (i=0; i<SHA256_DIGEST_LENGTH; ++i) {
        if (checksum[i] != 0) {
            isEmpty = 0;  // If any byte of the checksum is non-zero, then it's not empty
            break;
        }
    }

    fwrite(&bytesRead, sizeof(int), 1, fp_write);  // Save the number of bytes read to file
    fwrite(checksum, SHA256_DIGEST_LENGTH, 1, fp_write);  // Save the checksum to file

    printf("Bytes Read: %d\n", bytesRead);
    if (isEmpty) {
        printf("Checksum is zero - buffer is empty.\n");
    } else {
        printf("Checksum: ");
        for(i=0; i<SHA256_DIGEST_LENGTH; ++i)
            printf("%02x", checksum[i]);  // Print the checksum in hexadecimal format
        printf("\n");
    }

    fclose(fp_read);
    fclose(fp_write);

    return 0;
}
```
You can adjust the buffer size as per your needs. Also, please replace `"input.txt"` and `"output.txt"` with the paths to your actual input and output files. This program will read a file named "input.txt", calculate its checksum using SHA256, check if the checksum is zero (which implies that the buffer was empty), then write the number of bytes read and the checksum to another file named "output.txt".
']

