#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int run_command(char *username) {
    char command[50];
    sprintf(command, "id %s", username);
    return system(command);
}

void print_status(int status) {
    if (WIFEXITED(status)) {
        printf("The exit status of the command is: %d\n", WEXITSTATUS(status));
    } else {
        printf("The command did not terminate normally.\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr,"Usage: %s <username>\n", argv[0]);
        return 1;
    }

    int status = run_command(argv[1]);
    print_status(status);

    return 0;
}
```

You can compile and run the program with a command like this: `gcc -o idchecker idchecker.c && ./idchecker yourusername`

Please note that in Linux, when `system()` returns an integer, it's actually the status of the last command that was executed (as modified by shell builtins). To get the actual exit code you can use `WEXITSTATUS(status)` macro from wait.h. Also remember that this is not a safe method to execute commands with variable content without sanitizing user input, because it might be prone to shell injection attacks.
']

