```python
import sqlite3
from sqlite3 import Error

def create_connection():
    conn = None;
    try:
        # create a database connection
        conn = sqlite3.connect(':memory:') 
        print(sqlite3.version)
    except Error as e:
        print(e)

    if conn:
        return conn

def close_connection(conn):
    conn.close()

def create_table(conn):
    try:
        sql = """ CREATE TABLE IF NOT EXISTS subscribers (
                    id integer PRIMARY KEY,
                    email text NOT NULL
                ); """
        c = conn.cursor()
        c.execute(sql)
    except Error as e:
        print(e)

def insert_email(conn, email):
    try:
        sql = ''' INSERT INTO subscribers(email)
                  VALUES(?) '''
        cur = conn.cursor()
        cur.execute(sql, (email,))
        conn.commit()
        return cur.lastrowid
    except Error as e:
        print(e)

def unsubscribe(conn, email):
    try:
        sql = 'SELECT * FROM subscribers WHERE email=?'
        c = conn.cursor()
        c.execute(sql, (email,))

        data = c.fetchone()
        if data is not None:
            sql = 'DELETE FROM subscribers WHERE id=?'
            c.execute(sql, (data[0],))
            conn.commit()
            print("Unsubscribed successfully")
        else:
            print("Email not found in our database.")
    except Error as e:
        print(e)

def main():
    email = input("Please enter your email to unsubscribe: ")  # Get user's email

    conn = create_connection()
    with conn:
        create_table(conn)
        unsubscribe(conn, email)
    close_connection(conn)

if __name__ == '__main__':
    main()
```

In this code, `create_connection` function is used to connect to the SQLite database. The `unsubscribe` function is where most of our logic resides: it checks if the email exists in the database and, if so, deletes it. Please note that this is a very simplified example and not ready for production use.
